{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '이걸 크게 느껴도 되는지 스스로에게 물어보시는 것 자체가 그 패턴이 몸에 배어 있다는 뜻'이라고 짚은 지점에서, 내담자가 자기 감정의 크기를 스스로 판단하고 축소하는 것이 '나를 앞세우는 것은 이기적인 일이다'라는 핵심 신념에서 비롯됨. 성장 배경에서 자기 것을 요구하면 '이기적이다'라는 핀잔을 받은 경험이 이 신념의 근원."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '별거 아닌 건데', '탓은 아닌데', '이걸 크게 느껴도 되는 건지 모르겠어요'라고 말하며 자기 감정의 정당성을 스스로 묻는 태도가 '내 필요나 힘듦을 앞세우는 것은 이기적이고 부끄러운 일이다'라는 중간 신념과 직접 연결됨."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/1"],
      "relevance": "상담사가 '별거 아닌 건데'라고 시작하신 부분을 짚었을 때, 내담자가 자기 상태를 '괜찮아요, 별거 아니에요'로 숨기는 대응 방식이 드러남. 상황 사례에서 가족 모임 후 '피곤해서 그래'라고 넘긴 패턴과 동일."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 아이에게 소리를 지른 뒤 심한 죄책감을 느끼는 것이, 쌓인 피로와 서운함이 폭발한 후 죄책감으로 만회하려는 패턴에 해당. 상황 사례에서 '왜 아무도 나한테는 힘드냐고 안 물어보지'라는 서운함이 억눌리던 구조가 동일."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '아무도 저한테 괜찮냐고 물어보는 사람이 없는 것 같다'고 한 말이, 타인의 욕구는 챙기되 자기 욕구는 인식조차 하지 못하는 타인중심성 패턴을 보여줌. 명절 준비·간병을 당연하게 맡는 상황과 구조가 같음."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/situations/3"],
      "relevance": "내담자가 '사람들 한가운데 있어도 혼자였다'고 말한 것이, 도움이나 공감을 요청하지 못하고 혼자 감당하다 지치는 패턴과 연결됨. 배우자가 '당신은 뭘 원하는지 모르겠다'고 한 상황에서 자기 욕구를 인식조차 못 한 것과 같은 구조."
    }
  ]
}

